#include <list>
#include <iostream>

int main() {
    std::list<int> l = {1, 2, 2, 3, 3, 3, 4, 1, 1};

    l.unique();
    // l is now {1, 2, 3, 4, 1} 
    // (The final '1' is kept because it was not consecutive to the first '1')

    std::list<int> l_sorted = {1, 1, 2, 2, 3, 3};
    l_sorted.unique();
    // l_sorted is now {1, 2, 3}
}
